316	/// Compile and then export the document.
317	fn compile_and_export(
318	    world: &mut SystemWorld,
319	    config: &mut CompileConfig,
320	) -> Warned<SourceResult<Vec<Output>>> {
321	    match config.output_format {
322	        OutputFormat::Pdf | OutputFormat::Png | OutputFormat::Svg => {
323	            let Warned { output, warnings } = typst::compile::<PagedDocument>(world);
324	            let result = output.and_then(|document| export_paged(&document, config));
325	            Warned { output: result, warnings }
326	        }
327	        OutputFormat::Html => {
328	            let Warned { output, warnings } = typst::compile::<HtmlDocument>(world);
329	            let result = output.and_then(|document| export_html(&document, config));
330	            Warned {
331	                output: result.map(|()| vec![config.output.clone()]),
332	                warnings,
333	            }
334	        }
335	        OutputFormat::Bundle => {
336	            let Warned { output, warnings } = typst::compile::<Bundle>(world);
337	            let result = output.and_then(|bundle| export_bundle(bundle, config));
338	            Warned { output: result, warnings }
339	        }
340	    }
341	}
